#define CMD_BUFFER 4096
#define PATH_BUFFER 1024

/* --- String/number settings (mirrors sleep-unified.sh's CONFIGURATION
 * section exactly; "quoted" only matters for how these are written to the
 * config file for readability, both forms are accepted on read). --- */
typedef struct {
    const char *name;
    const char *label;
    const char *hint;
    const char *default_value;
    GtkWidget *entry;
    char current_value[PATH_BUFFER];
} ConfigVar;

static ConfigVar config_vars[] = {
    { "STATE_FILE",              "State file",                          "Where suspend/resume state is stored between the two halves of a run", "/tmp/sleep-unified.state", NULL, "" },
    { "STATE_MAXSIZE",           "State file max size (bytes)",         "State file is trimmed once it exceeds this size", "10240", NULL, "" },
    { "LOGFILE",                 "Log file",                            "Where everything that happens is logged", "/tmp/sleep-unified.log", NULL, "" },
    { "LOG_MAXSIZE",             "Log file max size (bytes)",           "Log file is trimmed once it exceeds this size", "10240", NULL, "" },
    { "SYNC_TIMEOUT",            "Sync timeout (seconds)",              "How long to wait for the pre-sleep sync before warning and aborting", "15", NULL, "" },
    { "UNMOUNT_TIMEOUT",         "USB unmount timeout (seconds)",       "How long to keep retrying an external USB disk unmount before giving up", "15", NULL, "" },
    { "RELEASE_TIMEOUT",         "Device release timeout (seconds)",    "How long to wait, after a lazy unmount, for the disk to show no pending I/O before it's deauthorized", "10", NULL, "" },
    { "SPURIOUS_WAKE_THRESHOLD", "AC spurious-wake threshold (seconds)","How close a wake must be to a recorded AC-adapter event to be treated as that firmware behavior. Only relevant if your hardware wakes on AC adapter plug/unplug — most systems don't have this behavior and can ignore this setting", "5", NULL, "" },
    { "MAX_RESLEEP_ATTEMPTS",    "Max automatic re-sleep attempts",     "Safety cap on automatic re-sleeps in a row, so a real wake is never suppressed indefinitely", "3", NULL, "" },
    { "AC_EVENT_FILE",           "AC event timestamp file",             "Where the udev rule records the last AC adapter state-change time", "/tmp/ac-online-event-time", NULL, "" },
    { "AC_UDEV_RULE_PATH",       "AC udev rule path",                   "Where the AC-event-timestamp udev rule is installed", "/etc/udev/rules.d/99-ac-adapter-timestamp.rules", NULL, "" },
};
static const int config_var_count = sizeof(config_vars) / sizeof(config_vars[0]);

/* --- Stage toggles: each enables/disables one independent piece of the
 * pre-suspend/post-resume pipeline (both its pre-suspend action and its
 * matching post-resume restore, together as a pair). All default on. --- */
typedef struct {
    const char *name;
    const char *label;
    GtkWidget *checkbox;
    int current_value;
} ConfigToggle;

static ConfigToggle config_toggles[] = {
    { "ENABLE_CPU_GOVERNORS",         "CPU governors (switch to powersave, restore after)", NULL, 1 },
    { "ENABLE_RFKILL",                "Wi-Fi/Bluetooth blocking (rfkill)", NULL, 1 },
    { "ENABLE_NETWORK_INTERFACES",    "Network interfaces down/up", NULL, 1 },
    { "ENABLE_USB_WAKEUP_POWER",      "USB wakeup/autosuspend tuning", NULL, 1 },
    { "ENABLE_USB_DISK_SAFE_UNMOUNT", "Safe USB disk unmount/reconnect", NULL, 1 },
    { "ENABLE_SATA_POWER_MANAGEMENT", "SATA/SCSI disk power management", NULL, 1 },
    { "ENABLE_TOUCHPAD_RESTORE",      "Touchpad state save/restore", NULL, 1 },
    { "ENABLE_AC_SPURIOUS_WAKE",      "AC-adapter spurious-wake detection", NULL, 1 },
    { "ENABLE_SCREEN_DPMS",           "Screen power off/on (X11/Wayland)", NULL, 1 },
    { "ENABLE_ACPI_WAKEUP_PRUNING",   "ACPI wakeup source pruning", NULL, 1 },
};
static const int config_toggle_count = sizeof(config_toggles) / sizeof(config_toggles[0]);

static char config_dir[PATH_BUFFER];
static char config_file[PATH_BUFFER + 16];

/* Resolve ~/.config/Unified_Sleep for the REAL invoking user (see the
 * header comment above for why $SUDO_USER is checked first). */
static void resolve_config_path(void) {
    const char *user = getenv("SUDO_USER");
    if (!user || !*user) user = getenv("USER");

    const char *home = NULL;
    if (user && *user) {
        struct passwd *pw = getpwnam(user);
        if (pw) home = pw->pw_dir;
    }
    if (!home) home = getenv("HOME");
    if (!home) home = "/root";

    snprintf(config_dir, sizeof(config_dir), "%s/.config/Unified_Sleep", home);
    snprintf(config_file, sizeof(config_file), "%s/config", config_dir);
}

/* Load current values: start from embedded defaults, then override with
 * whatever is found in config_file, if it exists. */
static void load_config(void) {
    for (int i = 0; i < config_var_count; i++) {
        strncpy(config_vars[i].current_value, config_vars[i].default_value, sizeof(config_vars[i].current_value) - 1);
    }
    for (int i = 0; i < config_toggle_count; i++) {
        config_toggles[i].current_value = 1;
    }

    FILE *f = fopen(config_file, "r");
    if (!f) return;

    char line[CMD_BUFFER];
    while (fgets(line, sizeof(line), f)) {
        size_t len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) line[--len] = '\0';
        if (line[0] == '#' || line[0] == '\0') continue;

        char *eq = strchr(line, '=');
        if (!eq) continue;
        *eq = '\0';
        char *name = line;
        char *val = eq + 1;
        size_t vlen = strlen(val);
        if (vlen >= 2 && val[0] == '"' && val[vlen-1] == '"') {
            val[vlen-1] = '\0';
            val++;
        }

        for (int i = 0; i < config_var_count; i++) {
            if (strcmp(name, config_vars[i].name) == 0) {
                strncpy(config_vars[i].current_value, val, sizeof(config_vars[i].current_value) - 1);
            }
        }
        for (int i = 0; i < config_toggle_count; i++) {
            if (strcmp(name, config_toggles[i].name) == 0) {
                config_toggles[i].current_value = (strcmp(val, "1") == 0) ? 1 : 0;
            }
        }
    }
    fclose(f);
}

/* Write all current values to config_file, creating the config directory
 * if needed. Returns 1 on success, 0 on failure. */
static int save_config(void) {
    char cmd[CMD_BUFFER];
    snprintf(cmd, sizeof(cmd), "mkdir -p '%s'", config_dir);
    if (system(cmd) != 0) return 0;

    FILE *f = fopen(config_file, "w");
    if (!f) return 0;

    fprintf(f, "# Unified Sleep Mode Optimization Framework — user settings\n");
    fprintf(f, "# Written by the --gui settings panel. Delete this file (or use\n");
    fprintf(f, "# \"Reset to Defaults\" in the GUI) to fall back to built-in defaults.\n\n");

    for (int i = 0; i < config_var_count; i++) {
        const char *val = config_vars[i].entry ? gtk_entry_get_text(GTK_ENTRY(config_vars[i].entry)) : config_vars[i].current_value;
        fprintf(f, "%s=\"%s\"\n", config_vars[i].name, val);
    }
    fprintf(f, "\n");
    for (int i = 0; i < config_toggle_count; i++) {
        int val = config_toggles[i].checkbox ? gtk_toggle_button_get_active(GTK_TOGGLE_BUTTON(config_toggles[i].checkbox)) : config_toggles[i].current_value;
        fprintf(f, "%s=%d\n", config_toggles[i].name, val ? 1 : 0);
    }

    fclose(f);
    return 1;
}

/* Run the embedded script via `bash -s`, feeding its bytes directly
 * through a pipe (no temporary file). Any extra_args are forwarded as
 * positional parameters ($1, $2, ...) inside the script. Environment
 * variables matching each config var/toggle name are set beforehand, so
 * the script's own CONFIGURATION section (which only assigns a variable
 * if it's not already set — see sleep-unified.sh) picks these up as
 * overrides automatically without needing its own config-file-reading
 * logic duplicated here.
 *
 * Returns the embedded script's exit status, or -1 on a fork/exec-level
 * failure before the script itself could even run. */
static int run_embedded_script(int extra_argc, char *extra_argv[]) {
    int pipefd[2];
    if (pipe(pipefd) != 0) return -1;

    pid_t pid = fork();
    if (pid < 0) {
        close(pipefd[0]);
        close(pipefd[1]);
        return -1;
    }

    if (pid == 0) {
        /* Child: stdin comes from the pipe's read end. */
        dup2(pipefd[0], STDIN_FILENO);
        close(pipefd[0]);
        close(pipefd[1]);

        for (int i = 0; i < config_var_count; i++) {
            setenv(config_vars[i].name, config_vars[i].current_value, 1);
        }
        for (int i = 0; i < config_toggle_count; i++) {
            setenv(config_toggles[i].name, config_toggles[i].current_value ? "1" : "0", 1);
        }

        char **args = malloc(sizeof(char *) * (extra_argc + 4));
        int ai = 0;
        args[ai++] = "bash";
        args[ai++] = "-s";
        args[ai++] = "--";
        for (int i = 0; i < extra_argc; i++) args[ai++] = extra_argv[i];
        args[ai] = NULL;

        execvp("bash", args);
        _exit(127); /* only reached if execvp fails */
    }

    /* Parent: write the embedded script to the pipe, then wait. */
    close(pipefd[0]);
    ssize_t written = 0;
    while ((size_t)written < embedded_script_len) {
        ssize_t n = write(pipefd[1], embedded_script + written, embedded_script_len - written);
        if (n <= 0) break;
        written += n;
    }
    close(pipefd[1]);

    int status = 0;
    waitpid(pid, &status, 0);
    if (WIFEXITED(status)) return WEXITSTATUS(status);
    return -1;
}

static void about_clicked_cb(GtkButton *btn, gpointer data) {
    (void)btn; (void)data;
    const char *about_text =
        "Unified Sleep Mode Optimization Framework\n"
        "Author: Maksym Nazar.\n"
        "Created with the assistance of Claude, ChatGPT, and Perplexity.\n\n"
        "This program prepares the system for suspend, performs the actual\n"
        "suspend, and restores the previous hardware state on resume: CPU\n"
        "governors, Wi-Fi/Bluetooth (rfkill), network interfaces, USB storage\n"
        "devices (safely unmounted before sleep and remounted after), USB\n"
        "wakeup/power settings, SATA/SCSI disk power management, touchpad\n"
        "state, and screen power (X11 and Wayland).\n\n"
        "It also includes a workaround for a firmware behavior on some hardware\n"
        "where changing the AC adapter's connection state while asleep wakes\n"
        "the system almost instantly: when detected, it goes straight back to\n"
        "sleep on its own, up to a configurable number of attempts.\n\n"
        "This settings panel lets you view and edit tunable values, toggle\n"
        "individual pipeline stages on or off, trigger a sleep cycle manually,\n"
        "reset to defaults, and view the version history.\n\n"
        "See Terms of Use and License for more info.";
    GtkWidget *dlg = gtk_dialog_new_with_buttons("About", NULL, GTK_DIALOG_MODAL,
                                                "OK", GTK_RESPONSE_OK, NULL);
    GtkWidget *content = gtk_dialog_get_content_area(GTK_DIALOG(dlg));
    GtkWidget *scroll = gtk_scrolled_window_new(NULL, NULL);
    gtk_widget_set_size_request(scroll, 560, 340);
    gtk_container_add(GTK_CONTAINER(content), scroll);
    GtkWidget *box = gtk_box_new(GTK_ORIENTATION_VERTICAL, 10);
    gtk_container_set_border_width(GTK_CONTAINER(box), 14);
    gtk_container_add(GTK_CONTAINER(scroll), box);
    GtkWidget *label = gtk_label_new(NULL);
    gtk_label_set_text(GTK_LABEL(label), about_text);
    gtk_label_set_xalign(GTK_LABEL(label), 0.0);
    gtk_label_set_line_wrap(GTK_LABEL(label), TRUE);
    gtk_label_set_line_wrap_mode(GTK_LABEL(label), PANGO_WRAP_WORD_CHAR);
    gtk_container_add(GTK_CONTAINER(box), label);
    gtk_widget_show_all(dlg);
    gtk_dialog_run(GTK_DIALOG(dlg));
    gtk_widget_destroy(dlg);
}

static void show_text_popup(const char *title, const char *text) {
    GtkWidget *dlg = gtk_dialog_new_with_buttons(title, NULL, GTK_DIALOG_MODAL, "OK", GTK_RESPONSE_OK, NULL);
    GtkWidget *content = gtk_dialog_get_content_area(GTK_DIALOG(dlg));
    GtkWidget *scroll = gtk_scrolled_window_new(NULL, NULL);
    gtk_widget_set_size_request(scroll, 700, 600);
    gtk_container_add(GTK_CONTAINER(content), scroll);
    GtkWidget *box = gtk_box_new(GTK_ORIENTATION_VERTICAL, 10);
    
    gtk_widget_set_margin_start(box, 14);
    gtk_widget_set_margin_end(box, 25);
    gtk_widget_set_margin_top(box, 14);
    gtk_widget_set_margin_bottom(box, 14);
    
    gtk_container_add(GTK_CONTAINER(scroll), box);
    GtkWidget *label = gtk_label_new(NULL);
    gtk_label_set_text(GTK_LABEL(label), text);
    gtk_label_set_xalign(GTK_LABEL(label), 0.0);
    gtk_label_set_line_wrap(GTK_LABEL(label), TRUE);
    gtk_container_add(GTK_CONTAINER(box), label);
    gtk_widget_show_all(dlg);
    gtk_dialog_run(GTK_DIALOG(dlg));
    gtk_widget_destroy(dlg);
}
