static void version_history_clicked_cb(GtkButton *btn, gpointer data) {
    (void)btn; (void)data;
    show_text_popup("Version History",
"VERSION HISTORY (condensed, newest first)\n\n"
"1.1 — Reordered settings fields (State file / State file max size / Log\n"
"file / Log file max size). Clarified that the AC spurious-wake threshold\n"
"only matters on hardware with that specific firmware behavior. Changing the\n"
"AC udev rule path now removes the old rule file left at the previous\n"
"path, instead of leaving it behind unreferenced. Replaced the Python\n"
"regeneration helper with a bash one.\n\n"
"1.0 — Compiled into a single binary: no arguments runs the sleep/resume\n"
"logic (embedded from sleep-unified.sh) directly; --gui opens this\n"
"settings panel. Added ten independent stage toggles, an external\n"
"per-user config file, and Reset to Defaults.\n\n"
"0.98 — Added touchpad state save/restore, working around a firmware\n"
"behavior where the AC-adapter WMI event reuses the touchpad-toggle code.\n\n"
"0.97 — Added the in-script README and CONFIGURATION section, corrected\n"
"the usage documentation, and removed subjective wording from comments.\n\n"
"0.96 — Public-release readiness: filesystem-agnostic disk release check\n"
"(works for any filesystem, not just NTFS/exFAT), Wayland screen on/off\n"
"support, and various wording/portability cleanups.\n\n"
"0.95 — The udev rule is now installed automatically by the script if\n"
"missing, instead of requiring a separate manual install step.\n\n"
"0.94 — Extended AC spurious-wake detection to cover unplugging the\n"
"adapter, not just plugging it in.\n\n"
"0.93 — Security fix: Wi-Fi/Bluetooth were never actually being blocked\n"
"before sleep due to a parsing bug; fixed.\n\n"
"0.92 — Added diagnostic rfkill-state logging at each wake.\n\n"
"0.91 — Simplified the udev rule to a single self-contained file.\n\n"
"0.90 — Replaced dmesg-based AC-event detection with a companion udev rule\n"
"(more reliable across different hardware/firmware).\n\n"
"0.89 — Added automatic re-sleep for a firmware behavior where an AC-adapter\n"
"state change while asleep wakes the system almost instantly.\n\n"
"0.88 — Fixed detection of USB network-tethering devices (e.g. a phone in\n"
"USB-modem mode) for post-resume recovery, and switched their recovery to\n"
"a full USB reauthorization cycle instead of an ineffective driver rebind.\n\n"
"0.87 — Reverted 0.86: no process holding a file open is ever signalled or\n"
"killed. Applications keep running; only a safe unmount path is used.\n\n"
"0.86 — (Later reverted in 0.87.) Added SIGTERM/SIGKILL escalation for\n"
"processes blocking a USB disk unmount.\n\n"
"0.85 — Notifications now always print to the console in addition to any\n"
"GUI dialog, and GUI dialogs are only attempted when a display is actually\n"
"present. Added notify-send/xmessage/yad/whiptail as further fallbacks.\n\n"
"0.84 — Removed a dead, non-functional state check left over from before\n"
"the state array existed at that point in execution. No behavior change.\n\n"
"0.83 — Fixed partition detection for USB disks where partitions are\n"
"nested one level deeper than expected (e.g. block/sdb/sdb1), which had\n"
"caused unmounts to be silently skipped.\n\n"
"0.82 — Fixed a race: USB disks could be granted permission to spin down\n"
"before being safely unmounted. SATA/SCSI power management now runs after\n"
"USB disks are disconnected, not before.\n\n"
"0.81 — Baseline for version-tracked history (earlier development wasn't\n"
"version-logged): pre-suspend hardware prep (ACPI wakeup, CPU\n"
"governors, rfkill, network interfaces, USB wakeup/power, SATA power\n"
"management), USB storage disconnect/reconnect, and matching post-resume\n"
"restore.\n");
}

static void reset_defaults_clicked_cb(GtkButton *btn, gpointer data) {
    (void)btn; (void)data;
    GtkWidget *confirm = gtk_message_dialog_new(NULL, GTK_DIALOG_MODAL, GTK_MESSAGE_QUESTION,
                                                 GTK_BUTTONS_YES_NO,
                                                 "This will delete %s and reset every setting shown here "
                                                 "back to its built-in default.\n\nContinue?",
                                                 config_file);
    int response = gtk_dialog_run(GTK_DIALOG(confirm));
    gtk_widget_destroy(confirm);
    if (response != GTK_RESPONSE_YES) return;

    remove(config_file);
    load_config();

    for (int i = 0; i < config_var_count; i++) {
        if (config_vars[i].entry) {
            gtk_entry_set_text(GTK_ENTRY(config_vars[i].entry), config_vars[i].current_value);
        }
    }
    for (int i = 0; i < config_toggle_count; i++) {
        if (config_toggles[i].checkbox) {
            gtk_toggle_button_set_active(GTK_TOGGLE_BUTTON(config_toggles[i].checkbox), config_toggles[i].current_value);
        }
    }

    GtkWidget *info = gtk_message_dialog_new(NULL, GTK_DIALOG_MODAL, GTK_MESSAGE_INFO,
                                              GTK_BUTTONS_OK, "Reset to defaults.");
    gtk_dialog_run(GTK_DIALOG(info));
    gtk_widget_destroy(info);
}

static void save_settings_clicked_cb(GtkButton *btn, gpointer data) {
    (void)btn; (void)data;

    /* If AC_UDEV_RULE_PATH is being changed, the rule file at the OLD
     * location becomes unreferenced by anything (sleep-unified.sh only
     * ever looks at the current AC_UDEV_RULE_PATH) and would otherwise be
     * left behind forever. Offer to delete it now, while we still know
     * both the old and new value — no separate system-wide tracking file
     * needed for this, since the config file we're about to write already
     * captures the "before" state via config_vars[i].current_value. */
    for (int i = 0; i < config_var_count; i++) {
        if (strcmp(config_vars[i].name, "AC_UDEV_RULE_PATH") != 0) continue;
        if (!config_vars[i].entry) break;

        const char *old_path = config_vars[i].current_value;
        const char *new_path = gtk_entry_get_text(GTK_ENTRY(config_vars[i].entry));

        if (strcmp(old_path, new_path) != 0 && access(old_path, F_OK) == 0) {
            GtkWidget *ask = gtk_message_dialog_new(NULL, GTK_DIALOG_MODAL, GTK_MESSAGE_QUESTION,
                                                     GTK_BUTTONS_YES_NO,
                                                     "AC udev rule path is changing:\n\n  %s\n  -> %s\n\n"
                                                     "The old rule file will no longer be used by anything. "
                                                     "Delete it now?",
                                                     old_path, new_path);
            int response = gtk_dialog_run(GTK_DIALOG(ask));
            gtk_widget_destroy(ask);
            if (response == GTK_RESPONSE_YES) {
                if (remove(old_path) == 0) {
                    system("command -v udevadm >/dev/null 2>&1 && udevadm control --reload-rules 2>/dev/null");
                } else {
                    GtkWidget *err = gtk_message_dialog_new(NULL, GTK_DIALOG_MODAL, GTK_MESSAGE_ERROR,
                                                             GTK_BUTTONS_OK,
                                                             "Could not delete %s (%s). You may need to "
                                                             "remove it manually.", old_path, strerror(errno));
                    gtk_dialog_run(GTK_DIALOG(err));
                    gtk_widget_destroy(err);
                }
            }
        }
        break;
    }

    int ok = save_config();
    GtkWidget *result_dlg;
    if (ok) {
        result_dlg = gtk_message_dialog_new(NULL, GTK_DIALOG_MODAL, GTK_MESSAGE_INFO,
                                             GTK_BUTTONS_OK, "Settings saved to %s", config_file);
        /* Keep current_value in sync with what was just saved, so a
         * second Save in the same session compares against the right
         * "old" value rather than the value from when the GUI opened. */
        for (int i = 0; i < config_var_count; i++) {
            if (config_vars[i].entry) {
                strncpy(config_vars[i].current_value, gtk_entry_get_text(GTK_ENTRY(config_vars[i].entry)),
                         sizeof(config_vars[i].current_value) - 1);
            }
        }
    } else {
        result_dlg = gtk_message_dialog_new(NULL, GTK_DIALOG_MODAL, GTK_MESSAGE_ERROR,
                                             GTK_BUTTONS_OK, "Could not save settings to %s (%s)",
                                             config_file, strerror(errno));
    }
    gtk_dialog_run(GTK_DIALOG(result_dlg));
    gtk_widget_destroy(result_dlg);
}

static void sleep_now_clicked_cb(GtkButton *btn, gpointer data) {
    (void)btn; (void)data;
    GtkWidget *confirm = gtk_message_dialog_new(NULL, GTK_DIALOG_MODAL, GTK_MESSAGE_QUESTION,
                                                 GTK_BUTTONS_YES_NO,
                                                 "This will put the system to sleep now, using the currently "
                                                 "displayed settings (whether or not you've saved them).\n\n"
                                                 "Continue?");
    int response = gtk_dialog_run(GTK_DIALOG(confirm));
    gtk_widget_destroy(confirm);
    if (response != GTK_RESPONSE_YES) return;

    /* Pull whatever is currently shown in the fields (even if unsaved) into
     * current_value, so the sleep cycle uses exactly what's on screen. */
    for (int i = 0; i < config_var_count; i++) {
        if (config_vars[i].entry) {
            strncpy(config_vars[i].current_value, gtk_entry_get_text(GTK_ENTRY(config_vars[i].entry)),
                     sizeof(config_vars[i].current_value) - 1);
        }
    }
    for (int i = 0; i < config_toggle_count; i++) {
        if (config_toggles[i].checkbox) {
            config_toggles[i].current_value = gtk_toggle_button_get_active(GTK_TOGGLE_BUTTON(config_toggles[i].checkbox));
        }
    }

    pid_t pid = fork();
    if (pid == 0) {
        /* Detach from the GUI's process group/session so putting the
         * system to sleep doesn't wait on or block the parent GTK
         * process, and so it keeps running independently of the GUI. */
        setsid();
        int status = run_embedded_script(0, NULL);
        _exit(status < 0 ? 1 : status);
    }
}

static void exit_clicked_cb(GtkButton *btn, gpointer data) {
    (void)btn; (void)data;
    gtk_main_quit();
}

/* Decodes embedded_icon_png into a GdkPixbuf. Returns NULL (and logs to
 * stderr) if decoding fails for any reason — the GUI still works fine
 * without an icon, this is purely cosmetic. */
static GdkPixbuf *load_embedded_icon(void) {
    GError *error = NULL;
    GdkPixbufLoader *loader = gdk_pixbuf_loader_new();

    if (!gdk_pixbuf_loader_write(loader, embedded_icon_png, embedded_icon_png_len, &error)) {
        fprintf(stderr, "Could not load embedded icon: %s\n", error ? error->message : "unknown error");
        if (error) g_error_free(error);
        gdk_pixbuf_loader_close(loader, NULL);
        g_object_unref(loader);
        return NULL;
    }
    if (!gdk_pixbuf_loader_close(loader, &error)) {
        fprintf(stderr, "Could not finalize embedded icon: %s\n", error ? error->message : "unknown error");
        if (error) g_error_free(error);
        g_object_unref(loader);
        return NULL;
    }

    GdkPixbuf *pixbuf = gdk_pixbuf_loader_get_pixbuf(loader);
    if (pixbuf) g_object_ref(pixbuf);
    g_object_unref(loader);
    return pixbuf;
}

static void run_gui(void) {
    gtk_init(NULL, NULL);

    GdkPixbuf *icon = load_embedded_icon();
    if (icon) {
        /* Applies as the process-wide default (used for dialogs opened
         * later: About, Terms, License, Version History, confirmation
         * prompts) as well as explicitly on the main window below — some
         * window managers prioritize a window's own icon over the
         * process-wide default, so both are set. GTK takes its own
         * reference in both calls, so our reference is only released once,
         * after both. */
        gtk_window_set_default_icon(icon);
    }

    GtkWidget *window = gtk_window_new(GTK_WINDOW_TOPLEVEL);
    gtk_window_set_title(GTK_WINDOW(window), "Unified Sleep Mode Optimization Framework");
    gtk_container_set_border_width(GTK_CONTAINER(window), 14);
    gtk_window_set_position(GTK_WINDOW(window), GTK_WIN_POS_CENTER);
    g_signal_connect(window, "destroy", G_CALLBACK(gtk_main_quit), NULL);
    if (icon) {
        gtk_window_set_icon(GTK_WINDOW(window), icon);
        g_object_unref(icon);
    }

    GtkWidget *scroll_outer = gtk_scrolled_window_new(NULL, NULL);
    gtk_scrolled_window_set_policy(GTK_SCROLLED_WINDOW(scroll_outer), GTK_POLICY_NEVER, GTK_POLICY_AUTOMATIC);
    gtk_widget_set_size_request(scroll_outer, 780, 640);
    gtk_container_add(GTK_CONTAINER(window), scroll_outer);

    GtkWidget *outer_box = gtk_box_new(GTK_ORIENTATION_VERTICAL, 12);
    gtk_container_set_border_width(GTK_CONTAINER(outer_box), 4);
    gtk_widget_set_margin_end(outer_box, 28); /* clearance so the scrollbar doesn't overlap hint text */
    gtk_container_add(GTK_CONTAINER(scroll_outer), outer_box);

    GtkWidget *config_label = gtk_label_new(NULL);
    char config_label_text[PATH_BUFFER + 32];
    snprintf(config_label_text, sizeof(config_label_text), "Settings file: %s", config_file);
    gtk_label_set_text(GTK_LABEL(config_label), config_label_text);
    gtk_label_set_xalign(GTK_LABEL(config_label), 0.0);
    gtk_box_pack_start(GTK_BOX(outer_box), config_label, FALSE, FALSE, 0);

    GtkWidget *sep_top = gtk_separator_new(GTK_ORIENTATION_HORIZONTAL);
    gtk_box_pack_start(GTK_BOX(outer_box), sep_top, FALSE, FALSE, 4);

    /* --- Values grid --- */
    GtkWidget *values_header = gtk_label_new("Values");
    gtk_label_set_xalign(GTK_LABEL(values_header), 0.0);
    gtk_box_pack_start(GTK_BOX(outer_box), values_header, FALSE, FALSE, 0);

    GtkWidget *grid = gtk_grid_new();
    gtk_grid_set_row_spacing(GTK_GRID(grid), 8);
    gtk_grid_set_column_spacing(GTK_GRID(grid), 10);
    gtk_box_pack_start(GTK_BOX(outer_box), grid, FALSE, FALSE, 0);

    for (int i = 0; i < config_var_count; i++) {
        GtkWidget *label = gtk_label_new(config_vars[i].label);
        gtk_label_set_xalign(GTK_LABEL(label), 0.0);
        gtk_grid_attach(GTK_GRID(grid), label, 0, i, 1, 1);

        GtkWidget *entry = gtk_entry_new();
        gtk_widget_set_size_request(entry, 320, -1);
        gtk_entry_set_text(GTK_ENTRY(entry), config_vars[i].current_value);
        gtk_widget_set_tooltip_text(entry, config_vars[i].hint);
        gtk_grid_attach(GTK_GRID(grid), entry, 1, i, 1, 1);
        config_vars[i].entry = entry;

        GtkWidget *hint_label = gtk_label_new(config_vars[i].hint);
        gtk_label_set_xalign(GTK_LABEL(hint_label), 0.0);
        GtkStyleContext *ctx = gtk_widget_get_style_context(hint_label);
        gtk_style_context_add_class(ctx, "dim-label");
        gtk_label_set_line_wrap(GTK_LABEL(hint_label), TRUE);
        gtk_widget_set_size_request(hint_label, 320, -1);
        gtk_grid_attach(GTK_GRID(grid), hint_label, 2, i, 1, 1);
    }

    GtkWidget *sep_mid1 = gtk_separator_new(GTK_ORIENTATION_HORIZONTAL);
    gtk_box_pack_start(GTK_BOX(outer_box), sep_mid1, FALSE, FALSE, 8);

    /* --- Stage toggles --- */
    GtkWidget *toggles_header = gtk_label_new("Pipeline stages (each can be switched off independently)");
    gtk_label_set_xalign(GTK_LABEL(toggles_header), 0.0);
    gtk_box_pack_start(GTK_BOX(outer_box), toggles_header, FALSE, FALSE, 0);

    GtkWidget *toggles_box = gtk_box_new(GTK_ORIENTATION_VERTICAL, 4);
    gtk_box_pack_start(GTK_BOX(outer_box), toggles_box, FALSE, FALSE, 0);

    for (int i = 0; i < config_toggle_count; i++) {
        GtkWidget *chk = gtk_check_button_new_with_label(config_toggles[i].label);
        gtk_toggle_button_set_active(GTK_TOGGLE_BUTTON(chk), config_toggles[i].current_value);
        gtk_box_pack_start(GTK_BOX(toggles_box), chk, FALSE, FALSE, 0);
        config_toggles[i].checkbox = chk;
    }

    GtkWidget *sep_mid2 = gtk_separator_new(GTK_ORIENTATION_HORIZONTAL);
    gtk_box_pack_start(GTK_BOX(outer_box), sep_mid2, FALSE, FALSE, 8);

    /* --- Actions --- */
    GtkWidget *action_box = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 8);
    gtk_box_pack_start(GTK_BOX(outer_box), action_box, FALSE, FALSE, 0);

    GtkWidget *btn_save = gtk_button_new_with_label("Save Settings");
    gtk_box_pack_start(GTK_BOX(action_box), btn_save, FALSE, FALSE, 0);
    g_signal_connect(btn_save, "clicked", G_CALLBACK(save_settings_clicked_cb), NULL);

    GtkWidget *btn_reset = gtk_button_new_with_label("Reset to Defaults");
    gtk_box_pack_start(GTK_BOX(action_box), btn_reset, FALSE, FALSE, 0);
    g_signal_connect(btn_reset, "clicked", G_CALLBACK(reset_defaults_clicked_cb), NULL);

    GtkWidget *btn_sleep_now = gtk_button_new_with_label("Sleep Now");
    gtk_box_pack_start(GTK_BOX(action_box), btn_sleep_now, FALSE, FALSE, 0);
    g_signal_connect(btn_sleep_now, "clicked", G_CALLBACK(sleep_now_clicked_cb), NULL);

    GtkWidget *sep_bottom = gtk_separator_new(GTK_ORIENTATION_HORIZONTAL);
    gtk_box_pack_start(GTK_BOX(outer_box), sep_bottom, FALSE, FALSE, 8);

    GtkWidget *info_box = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 8);
    gtk_box_pack_start(GTK_BOX(outer_box), info_box, FALSE, FALSE, 0);

    GtkWidget *btn_history = gtk_button_new_with_label("Version History");
    gtk_box_pack_start(GTK_BOX(info_box), btn_history, FALSE, FALSE, 0);
    g_signal_connect(btn_history, "clicked", G_CALLBACK(version_history_clicked_cb), NULL);

    GtkWidget *btn_about = gtk_button_new_with_label("About");
    gtk_box_pack_start(GTK_BOX(info_box), btn_about, FALSE, FALSE, 0);
    g_signal_connect(btn_about, "clicked", G_CALLBACK(about_clicked_cb), NULL);

    GtkWidget *btn_terms = gtk_button_new_with_label("Terms of Use");
    gtk_box_pack_start(GTK_BOX(info_box), btn_terms, FALSE, FALSE, 0);
    g_signal_connect(btn_terms, "clicked", G_CALLBACK(terms_clicked_cb), NULL);

    GtkWidget *btn_license = gtk_button_new_with_label("License");
    gtk_box_pack_start(GTK_BOX(info_box), btn_license, FALSE, FALSE, 0);
    g_signal_connect(btn_license, "clicked", G_CALLBACK(license_clicked_cb), NULL);

    GtkWidget *btn_exit = gtk_button_new_with_label("Exit");
    gtk_box_pack_start(GTK_BOX(info_box), btn_exit, FALSE, FALSE, 0);
    g_signal_connect(btn_exit, "clicked", G_CALLBACK(exit_clicked_cb), NULL);

    gtk_widget_show_all(window);
    gtk_main();
}

int main(int argc, char *argv[]) {
    resolve_config_path();
    load_config();

    int want_gui = 0;
    int first_pass_through_arg = argc;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--gui") == 0 || strcmp(argv[i], "-g") == 0) {
            want_gui = 1;
        } else if (first_pass_through_arg == argc) {
            first_pass_through_arg = i;
        }
    }

    if (want_gui) {
        if (!getenv("DISPLAY") && !getenv("WAYLAND_DISPLAY")) {
            fprintf(stderr, "--gui requires a graphical session (no $DISPLAY or $WAYLAND_DISPLAY found).\n");
            return 1;
        }
        run_gui();
        return 0;
    }

    /* Default: run the embedded sleep/resume logic directly, forwarding
     * any arguments that weren't --gui/-g. */
    int extra_argc = (first_pass_through_arg < argc) ? argc - first_pass_through_arg : 0;
    char **extra_argv = (first_pass_through_arg < argc) ? &argv[first_pass_through_arg] : NULL;

    int status = run_embedded_script(extra_argc, extra_argv);
    if (status < 0) {
        fprintf(stderr, "Failed to run the embedded sleep/resume script.\n");
        return 1;
    }
    return status;
}
